      justify-content: flex-end;
      gap: 0.25rem;
      list-style: none;
      margin: 0;
      padding: 0;
    }

    .main-nav a {
      display: inline-flex;
      align-items: center;
      min-height: 2.75rem;
      padding: 0.5rem 0.9rem;
      border-radius: 999px;
      text-decoration: none;
    }

    .main-nav a:hover,
    .main-nav a:focus-visible {
      background: var(--surface-strong);
    }

    main {
      padding: 1.5rem 0 4rem;
    }

    .hero {
      display: grid;
      grid-template-columns: 1.15fr 0.85fr;
      gap: 1.5rem;
      align-items: stretch;
      margin-top: 0.75rem;
    }

    .hero-copy,
    .hero-aside,
    .section-card {
      background: color-mix(in srgb, var(--surface) 88%, transparent);
      border: 1px solid color-mix(in srgb, var(--line) 84%, transparent);
      border-radius: var(--radius-xl);
      box-shadow: var(--shadow);
    }

    .hero-copy {
      padding: clamp(1.35rem, 2vw, 2.25rem);
      display: grid;
      align-content: center;
      min-width: 0;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      width: fit-content;
      margin: 0 0 1rem;
      padding: 0.45rem 0.75rem;
      border-radius: 999px;
      background: var(--accent-soft);
      color: var(--accent-strong);
      font-weight: 700;
      font-size: 0.94rem;
    }

    h1,
    h2,
    h3,
    p {
      margin-top: 0;
    }

    h1 {
      font-size: clamp(2.5rem, 5vw, 4.8rem);
      line-height: 0.96;
      letter-spacing: -0.05em;
      margin-bottom: 1rem;
      max-width: 11ch;
    }

    .lede {
      font-size: clamp(1.05rem, 1.4vw, 1.18rem);
      color: var(--muted);
      max-width: 42ch;
      margin-bottom: 1.5rem;
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      margin-bottom: 1.5rem;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 3rem;
      padding: 0.72rem 1.2rem;
      border-radius: 999px;
      border: 1px solid transparent;
      text-decoration: none;
      font-weight: 700;
      transition: transform 120ms ease, background-color 120ms ease, border-color 120ms ease;
    }

    .btn:hover {
      transform: translateY(-1px);
    }

    .btn-primary {
      background: var(--text);
      color: var(--surface-strong);
    }

    .btn-primary:hover,
    .btn-primary:focus-visible {
      background: var(--accent-strong);
      color: var(--surface-strong);
    }

    .btn-secondary {
      background: var(--surface-strong);
      color: var(--text);
      border-color: var(--line);
    }

    .btn-secondary:hover,
    .btn-secondary:focus-visible {
      border-color: var(--accent);
      color: var(--accent-strong);
    }

    .hero-stats {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 0.75rem;
      min-width: 0;
    }

    .stat {
      padding: 1rem;
      border-radius: 18px;
      background: var(--surface-strong);
      border: 1px solid color-mix(in srgb, var(--line) 72%, transparent);
      min-width: 0;
    }

    .stat strong {
      display: block;
      font-size: 1.2rem;
      margin-bottom: 0.15rem;
    }

    .stat span {
      color: var(--muted);
      font-size: 0.95rem;
    }

    .hero-aside {
      padding: 1rem;
      display: grid;
      gap: 1rem;
      overflow: hidden;
    }

    .promo-panel {
      position: relative;
      min-height: 100%;
      border-radius: 24px;
      overflow: hidden;
      background:
        linear-gradient(150deg, #f3dcc6 0%, #f7ece2 35%, #dbc0a5 100%);
      padding: 1.35rem;
      min-width: 0;
    }

    .promo-panel h2 {
      font-size: 1.25rem;
      margin-bottom: 0.75rem;
    }

    .promo-panel p {
      max-width: 24ch;
      color: #3f2c1f;
      margin-bottom: 1rem;
    }

    .promo-visual {
      margin-top: 1rem;
      display: grid;
      grid-template-columns: 1.2fr 0.8fr;
      gap: 0.75rem;
      align-items: stretch;
    }

    .promo-bag,
    .promo-card {
      border-radius: 20px;
      background: color-mix(in srgb, #ffffff 68%, transparent);
      border: 1px solid color-mix(in srgb, #ffffff 60%, transparent);
      min-width: 0;
    }

    .promo-bag {
      padding: 1rem;
      display: grid;
      align-content: end;
      min-height: 250px;
      background-image:
        radial-gradient(circle at 30% 25%, #ffffff 0 3%, transparent 3.2%),
        linear-gradient(180deg, #7b4a22 0%, #965e2f 100%);
      color: var(--surface-strong);
    }

    .promo-bag .label {
      display: inline-flex;
      width: fit-content;
      margin-bottom: auto;
      padding: 0.35rem 0.65rem;
      border-radius: 999px;
      background: #ffffff1a;
      font-size: 0.85rem;
    }

    .promo-bag .bag-price {
      font-size: 1.35rem;
      font-weight: 800;
      margin-bottom: 0.1rem;
    }

    .promo-card {
      padding: 1rem;
      display: grid;
      gap: 0.75rem;
    }

    .deal-timer {
      display: flex;
      flex-wrap: wrap;
      gap: 0.55rem;
    }

    .time-chip {
      flex: 1 1 5rem;
      text-align: center;
      padding: 0.7rem 0.45rem;
      border-radius: 16px;
      background: var(--surface-strong);
      border: 1px solid var(--line);
    }

    .time-chip strong {
      display: block;
      font-size: 1.2rem;
    }

    .time-chip span {
      color: var(--muted);
      font-size: 0.84rem;
    }

    .grid {
      display: grid;
      gap: 1.25rem;
    }

    .section-card {
      padding: clamp(1.25rem, 2vw, 1.8rem);
      margin-top: 1.5rem;
    }

    .section-head {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      align-items: end;
      gap: 1rem;
      margin-bottom: 1rem;
    }

    .section-head h2 {
      font-size: clamp(1.5rem, 2vw, 2rem);
      letter-spacing: -0.03em;
      margin-bottom: 0.25rem;
    }

    .section-head p {
      color: var(--muted);
      margin-bottom: 0;
      max-width: 48ch;
    }

    .filter-bar {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
    }

    .filter-btn {
      min-height: 2.6rem;
      padding: 0.55rem 1rem;
      border-radius: 999px;
      border: 1px solid var(--line);
      background: var(--surface-strong);
      color: var(--text);
      cursor: pointer;
    }

    .filter-btn[aria-pressed="true"] {
      background: var(--text);
      border-color: var(--text);
      color: var(--surface-strong);
    }

    .product-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1rem;
    }

    .product-card {
      display: grid;
      background: var(--surface-strong);
      border: 1px solid var(--line);
      border-radius: 24px;
      overflow: hidden;
      min-width: 0;
    }

    .product-media {
      aspect-ratio: 4 / 3;
      background: #f1e6db;
      position: relative;
      overflow: hidden;
    }

    .product-media img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .badge {
      position: absolute;
      left: 1rem;
      top: 1rem;
      display: inline-flex;
      align-items: center;
      padding: 0.35rem 0.65rem;
      border-radius: 999px;
      background: var(--surface-strong);
      font-size: 0.82rem;
      font-weight: 700;
      box-shadow: 0 8px 20px #00000014;
    }

    .product-body {
      display: grid;
      gap: 0.7rem;
      padding: 1rem;
    }

    .product-title {
      font-size: 1.02rem;
      font-weight: 750;
      margin-bottom: 0.15rem;
    }

    .product-meta {
      display: flex;
      justify-content: space-between;
      gap: 0.75rem;
      color: var(--muted);
      font-size: 0.94rem;
    }

    .price {
      font-weight: 800;
      color: var(--text);
      white-space: nowrap;
    }

    .product-actions {
      display: flex;
      gap: 0.5rem;
      flex-wrap: wrap;
      margin-top: 0.15rem;
    }

    .mini-btn {
      min-height: 2.6rem;
      padding: 0.5rem 0.9rem;
      border-radius: 999px;
      border: 1px solid var(--line);
      background: var(--surface);
      color: var(--text);
      cursor: pointer;
    }

    .mini-btn.primary {
      background: var(--text);
      border-color: var(--text);
      color: var(--surface-strong);
    }

    .mini-btn:hover,
    .mini-btn:focus-visible {
      border-color: var(--accent);
      color: var(--accent-strong);
    }

    .mini-btn.primary:hover,
    .mini-btn.primary:focus-visible {
      background: var(--accent-strong);
      border-color: var(--accent-strong);
      color: var(--surface-strong);
    }

    .deal-layout {
      display: grid;
      grid-template-columns: 1fr 1.15fr;
      gap: 1rem;
      align-items: stretch;
    }

    .deal-highlight {
      padding: 1.25rem;
      border-radius: 24px;
      background: linear-gradient(160deg, #fff3e6 0%, #f4deca 100%);
      border: 1px solid color-mix(in srgb, var(--line) 75%, transparent);
      min-width: 0;
    }

    .deal-highlight h3 {
      font-size: 1.45rem;
      margin-bottom: 0.6rem;
    }

    .deal-highlight p {
      color: var(--muted);
      margin-bottom: 1rem;
    }

    .deal-bundle {
      display: grid;
      gap: 0.85rem;
    }

    .deal-row {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      padding: 0.85rem 0;
      border-top: 1px solid color-mix(in srgb, var(--line) 88%, transparent);
      min-width: 0;
    }

    .deal-row:first-of-type {
      border-top: 0;
      padding-top: 0;
    }

    .deal-row strong {
      display: block;
      margin-bottom: 0.2rem;
    }

    .deal-row span {
      color: var(--muted);
      font-size: 0.94rem;
    }

    .deal-row .price {
      font-size: 1.05rem;
      align-self: center;
    }

    .editorial-grid {
      display: grid;
      grid-template-columns: 1.25fr 0.75fr;
      gap: 1rem;
      align-items: stretch;
    }

    .story-card {
      display: grid;
      grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
      gap: 0;
      background: var(--surface-strong);
      border: 1px solid var(--line);
      border-radius: 24px;
      overflow: hidden;
      min-width: 0;
    }

    .story-card figure {
      margin: 0;
      min-width: 0;
      min-height: 100%;
    }

    .story-card img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .story-body {
      padding: 1.2rem;
      display: grid;
      align-content: center;
      gap: 0.75rem;
      min-width: 0;
    }

    .story-body h3 {
      font-size: 1.35rem;
      margin-bottom: 0.15rem;
    }

    .story-body p {
      color: var(--muted);
      margin-bottom: 0;
    }

    .story-list {
      display: grid;
      gap: 0.85rem;
    }

    .story-mini {
      padding: 1rem;
      border-radius: 22px;
      background: var(--surface-strong);
      border: 1px solid var(--line);
      min-width: 0;
    }

    .story-mini p {
      color: var(--muted);
      margin-bottom: 0.85rem;
    }

    .story-mini a {
      font-weight: 700;
    }

    .status {
      margin-top: 0.9rem;
      min-height: 1.5rem;
      color: var(--success);
      font-weight: 650;
    }

    .footer {
      padding: 1.5rem 0 2.5rem;
      color: var(--muted);
    }

    .footer-inner {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: 1rem;
      padding-top: 1rem;
      border-top: 1px solid var(--line);
    }

    .footer-links {
      display: flex;
      flex-wrap: wrap;
      gap: 1rem;
    }

    :focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    @media (max-width: 1024px) {
      .hero,
      .deal-layout,
      .editorial-grid {
        grid-template-columns: 1fr;
      }

      .product-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .story-card {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width: 720px) {
      .header-inner {
        flex-direction: column;
        align-items: flex-start;
      }

      .main-nav {
        margin-left: 0;
        width: 100%;
      }

      .main-nav ul {
        justify-content: flex-start;
      }

      h1 {
        max-width: 12ch;
      }

      .hero-stats,
      .product-grid {
        grid-template-columns: 1fr;
      }

      .promo-visual {
        grid-template-columns: 1fr;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --surface: Canvas;
        --surface-strong: Canvas;
        --text: CanvasText;
        --muted: CanvasText;
        --line: ButtonBorder;
        --accent: LinkText;
        --accent-strong: LinkText;
        --accent-soft: Canvas;
        --success: CanvasText;
        --shadow: none;
        --focus: Highlight;
      }

      .site-header,
      .hero-copy,
      .hero-aside,
      .section-card,
      .product-card,
      .deal-highlight,
      .story-card,
      .story-mini,
      .stat,
      .promo-card {
        border-color: ButtonBorder;
        box-shadow: none;
      }

      .brand-mark,
      .promo-bag {
        background: ButtonFace;
        color: ButtonText;
        border: 1px solid ButtonBorder;
      }

      .btn-primary,
      .filter-btn[aria-pressed="true"],
      .mini-btn.primary {
        background: ButtonFace;
        color: ButtonText;
        border-color: ButtonText;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <header class="site-header">
    <div class="shell header-inner">
      <a class="brand" href="#top" aria-label="Northstar Retail home">
        <span class="brand-mark" aria-hidden="true">N</span>
        <span>Northstar Retail</span>
      </a>

      <nav class="main-nav" aria-label="Primary">
        <ul>
          <li><a href="#featured">Featured</a></li>
          <li><a href="#deals">Deals</a></li>
          <li><a href="#stories">Stories</a></li>
          <li><a href="#newsletter">Journal</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main id="main">
    <div class="shell" id="top">
      <section class="hero" aria-labelledby="hero-heading">
        <div class="hero-copy">
          <p class="eyebrow">New season, refined essentials</p>
          <h1 id="hero-heading">Modern pieces for every part of the week.</h1>
          <p class="lede">Discover elevated basics, special buys, and curated editorial picks designed to make a retail home page feel effortless, premium, and easy to shop.</p>
          <div class="hero-actions">
            <a class="btn btn-primary" href="#featured">Shop featured</a>
            <a class="btn btn-secondary" href="#deals">See today's deals</a>
          </div>
          <div class="hero-stats" aria-label="Store highlights">
            <div class="stat">
              <strong>120+</strong>
              <span>new arrivals this month</span>
            </div>
            <div class="stat">
              <strong>2-day</strong>
              <span>free shipping over $75</span>
            </div>
            <div class="stat">
              <strong>4.8/5</strong>
              <span>customer rating average</span>
            </div>
          </div>
        </div>

        <aside class="hero-aside" aria-label="Featured promotion">
          <div class="promo-panel">
            <p class="label">Limited time</p>
            <h2>Spring carryall bundle</h2>
            <p>Build a polished everyday rotation with a bag, knit, and shoe edit priced for the weekend.</p>
            <div class="promo-visual">
              <div class="promo-bag" aria-hidden="true">
                <span class="label">Best seller</span>
                <div class="bag-price">$118</div>
                <div>Canvas Carryall</div>
              </div>
              <div class="promo-card">
                <strong>Bundle savings</strong>
                <p style="margin:0;color:var(--muted);">Save 20% when you buy any three accessories.</p>
                <a class="btn btn-secondary" href="#deals" style="width:100%;">Shop the bundle</a>
              </div>
            </div>
          </div>
        </aside>
      </section>

      <section class="section-card" id="featured" aria-labelledby="featured-heading">
        <div class="section-head">
          <div>
            <h2 id="featured-heading">Featured products</h2>
            <p>Top picks across apparel, accessories, and home goods, with category filters for quick browsing.</p>
          </div>
          <div class="filter-bar" role="toolbar" aria-label="Product filters">
            <button class="filter-btn" type="button" data-filter="all" aria-pressed="true">All</button>
            <button class="filter-btn" type="button" data-filter="apparel" aria-pressed="false">Apparel</button>
            <button class="filter-btn" type="button" data-filter="accessories" aria-pressed="false">Accessories</button>
            <button class="filter-btn" type="button" data-filter="home" aria-pressed="false">Home</button>
          </div>
        </div>

        <div class="product-grid" id="product-grid">
          <article class="product-card" data-category="apparel">
            <div class="product-media">
              <span class="badge">New</span>
              <img src="https://images.unsplash.com/photo-1523398002811-999ca8dec234?auto=format&fit=crop&w=900&q=80" alt="Model wearing a cream tailored jacket and relaxed trousers">
            </div>
            <div class="product-body">
              <div>
                <div class="product-title">Relaxed Tailored Set</div>
                <div class="product-meta"><span>Apparel</span><span class="price">$148</span></div>
              </div>
              <div class="product-actions">
                <button class="mini-btn primary" type="button" data-add-to-bag="Relaxed Tailored Set">Add to bag</button>
                <button class="mini-btn" type="button" data-save="Relaxed Tailored Set">Save</button>
              </div>
            </div>
          </article>

          <article class="product-card" data-category="accessories">
            <div class="product-media">
              <span class="badge">Popular</span>
              <img src="https://images.unsplash.com/photo-1523170335258-f5ed11844a49?auto=format&fit=crop&w=900&q=80" alt="Leather crossbody bag on a neutral background">
            </div>
            <div class="product-body">
              <div>
                <div class="product-title">Leather Crossbody</div>
                <div class="product-meta"><span>Accessories</span><span class="price">$92</span></div>
              </div>
              <div class="product-actions">
                <button class="mini-btn primary" type="button" data-add-to-bag="Leather Crossbody">Add to bag</button>
                <button class="mini-btn" type="button" data-save="Leather Crossbody">Save</button>
              </div>
            </div>
          </article>

          <article class="product-card" data-category="home">
            <div class="product-media">
              <span class="badge">Editor pick</span>
              <img src="https://images.unsplash.com/photo-1484101403633-562f891dc89a?auto=format&fit=crop&w=900&q=80" alt="Minimal dining table with ceramic decor and soft daylight">
            </div>
            <div class="product-body">
              <div>
                <div class="product-title">Ceramic Table Edit</div>
                <div class="product-meta"><span>Home</span><span class="price">$64</span></div>
              </div>
              <div class="product-actions">
                <button class="mini-btn primary" type="button" data-add-to-bag="Ceramic Table Edit">Add to bag</button>
                <button class="mini-btn" type="button" data-save="Ceramic Table Edit">Save</button>
              </div>
            </div>
          </article>

          <article class="product-card" data-category="apparel">
            <div class="product-media">
              <span class="badge">Trending</span>
              <img src="https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?auto=format&fit=crop&w=900&q=80" alt="Neutral knit sweater folded neatly with soft texture visible">
            </div>
            <div class="product-body">
              <div>
                <div class="product-title">Everyday Knit Crew</div>
                <div class="product-meta"><span>Apparel</span><span class="price">$78</span></div>
              </div>
              <div class="product-actions">
                <button class="mini-btn primary" type="button" data-add-to-bag="Everyday Knit Crew">Add to bag</button>
                <button class="mini-btn" type="button" data-save="Everyday Knit Crew">Save</button>
              </div>
            </div>
          </article>
        </div>
        <p class="status" id="feature-status" aria-live="polite"></p>
      </section>

      <section class="section-card" id="deals" aria-labelledby="deals-heading">
        <div class="section-head">
          <div>
            <h2 id="deals-heading">Today's deals</h2>
            <p>Rotating offers built to spotlight bundles, markdowns, and a fast-moving featured deal.</p>
          </div>
          <a href="#newsletter">Get deal alerts</a>
        </div>

        <div class="deal-layout">
          <article class="deal-highlight">
            <h3>48-hour doorbuster</h3>
            <p>Our capsule sale refreshes automatically. Shop limited-time pricing before the clock runs out.</p>
            <div class="deal-timer" aria-label="Time remaining">
              <div class="time-chip"><strong id="days">02</strong><span>Days</span></div>
              <div class="time-chip"><strong id="hours">18</strong><span>Hours</span></div>
              <div class="time-chip"><strong id="minutes">24</strong><span>Minutes</span></div>
              <div class="time-chip"><strong id="seconds">00</strong><span>Seconds</span></div>
            </div>
          </article>

          <div class="deal-bundle" aria-label="Deal list">
            <div class="deal-row">
              <div>
                <strong>Buy 2, save 15% on denim</strong>
                <span>Denim across all fits and washes.</span>
              </div>
              <div class="price">Use code DENIM15</div>
            </div>
            <div class="deal-row">
              <div>
                <strong>Home refresh bundle</strong>
                <span>Mix any candle, tray, and vase.</span>
              </div>
              <div class="price">$88</div>
            </div>
            <div class="deal-row">
              <div>
                <strong>Members get free express shipping</strong>
                <span>Available on every order over $35.</span>
              </div>
              <div class="price">Join free</div>
