    }

    .section-card {
      padding: clamp(1.25rem, 2vw, 1.8rem);
      margin-top: 1.5rem;
    }

    .section-head {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      align-items: end;
      gap: 1rem;
      margin-bottom: 1rem;
    }

    .section-head h2 {
      font-size: clamp(1.5rem, 2vw, 2rem);
      letter-spacing: -0.03em;
      margin-bottom: 0.25rem;
    }

    .section-head p {
      color: var(--muted);
      margin-bottom: 0;
      max-width: 48ch;
    }

    .filter-bar {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
    }

    .filter-btn {
      min-height: 2.6rem;
      padding: 0.55rem 1rem;
      border-radius: 999px;
      border: 1px solid var(--line);
      background: var(--surface-strong);
      color: var(--text);
      cursor: pointer;
    }

    .filter-btn[aria-pressed="true"] {
      background: var(--text);
      border-color: var(--text);
      color: var(--surface-strong);
    }

    .product-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1rem;
    }

    .product-card {
      display: grid;
      background: var(--surface-strong);
      border: 1px solid var(--line);
      border-radius: 24px;
      overflow: hidden;
      min-width: 0;
    }

    .product-media {
      aspect-ratio: 4 / 3;
      background: #f1e6db;
      position: relative;
      overflow: hidden;
    }

    .product-media img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .badge {
      position: absolute;
      left: 1rem;
      top: 1rem;
      display: inline-flex;
      align-items: center;
      padding: 0.35rem 0.65rem;
      border-radius: 999px;
      background: var(--surface-strong);
      font-size: 0.82rem;
      font-weight: 700;
      box-shadow: 0 8px 20px #00000014;
    }

    .product-body {
      display: grid;
      gap: 0.7rem;
      padding: 1rem;
    }

    .product-title {
      font-size: 1.02rem;
      font-weight: 750;
      margin-bottom: 0.15rem;
    }

    .product-meta {
      display: flex;
      justify-content: space-between;
      gap: 0.75rem;
      color: var(--muted);
      font-size: 0.94rem;
    }

    .price {
      font-weight: 800;
      color: var(--text);
      white-space: nowrap;
    }

    .product-actions {
      display: flex;
      gap: 0.5rem;
      flex-wrap: wrap;
      margin-top: 0.15rem;
    }

    .mini-btn {
      min-height: 2.6rem;
      padding: 0.5rem 0.9rem;
      border-radius: 999px;
      border: 1px solid var(--line);
      background: var(--surface);
      color: var(--text);
      cursor: pointer;
    }

    .mini-btn.primary {
      background: var(--text);
      border-color: var(--text);
      color: var(--surface-strong);
    }

    .mini-btn:hover,
    .mini-btn:focus-visible {
      border-color: var(--accent);
      color: var(--accent-strong);
    }

    .mini-btn.primary:hover,
    .mini-btn.primary:focus-visible {
      background: var(--accent-strong);
      border-color: var(--accent-strong);
      color: var(--surface-strong);
    }

    .deal-layout {
      display: grid;
      grid-template-columns: 1fr 1.15fr;
      gap: 1rem;
      align-items: stretch;
    }

    .deal-highlight {
      padding: 1.25rem;
      border-radius: 24px;
      background: linear-gradient(160deg, #fff3e6 0%, #f4deca 100%);
      border: 1px solid color-mix(in srgb, var(--line) 75%, transparent);
      min-width: 0;
    }

    .deal-highlight h3 {
      font-size: 1.45rem;
      margin-bottom: 0.6rem;
    }

    .deal-highlight p {
      color: var(--muted);
      margin-bottom: 1rem;
    }

    .deal-bundle {
      display: grid;
      gap: 0.85rem;
    }

    .deal-row {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      padding: 0.85rem 0;
      border-top: 1px solid color-mix(in srgb, var(--line) 88%, transparent);
      min-width: 0;
    }

    .deal-row:first-of-type {
      border-top: 0;
      padding-top: 0;
    }

    .deal-row strong {
      display: block;
      margin-bottom: 0.2rem;
    }

    .deal-row span {
      color: var(--muted);
      font-size: 0.94rem;
    }

    .deal-row .price {
      font-size: 1.05rem;
      align-self: center;
    }

    .editorial-grid {
      display: grid;
      grid-template-columns: 1.25fr 0.75fr;
      gap: 1rem;
      align-items: stretch;
    }

    .story-card {
      display: grid;
      grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
      gap: 0;
      background: var(--surface-strong);
      border: 1px solid var(--line);
      border-radius: 24px;
      overflow: hidden;
      min-width: 0;
    }

    .story-card figure {
      margin: 0;
      min-width: 0;
      min-height: 100%;
    }

    .story-card img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .story-body {
      padding: 1.2rem;
      display: grid;
      align-content: center;
      gap: 0.75rem;
      min-width: 0;
    }

    .story-body h3 {
      font-size: 1.35rem;
      margin-bottom: 0.15rem;
    }

    .story-body p {
      color: var(--muted);
      margin-bottom: 0;
    }

    .story-list {
      display: grid;
      gap: 0.85rem;
    }

    .story-mini {
      padding: 1rem;
      border-radius: 22px;
      background: var(--surface-strong);
      border: 1px solid var(--line);
      min-width: 0;
    }

    .story-mini p {
      color: var(--muted);
      margin-bottom: 0.85rem;
    }

    .story-mini a {
      font-weight: 700;
    }

    .status {
      margin-top: 0.9rem;
      min-height: 1.5rem;
      color: var(--success);
      font-weight: 650;
    }

    .footer {
      padding: 1.5rem 0 2.5rem;
      color: var(--muted);
    }

    .footer-inner {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: 1rem;
      padding-top: 1rem;
      border-top: 1px solid var(--line);
    }

    .footer-links {
      display: flex;
      flex-wrap: wrap;
      gap: 1rem;
    }

    :focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    @media (max-width: 1024px) {
      .hero,
      .deal-layout,
      .editorial-grid {
        grid-template-columns: 1fr;
      }

      .product-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .story-card {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width: 720px) {
      .header-inner {
        flex-direction: column;
        align-items: flex-start;
      }

      .main-nav {
        margin-left: 0;
        width: 100%;
      }

      .main-nav ul {
        justify-content: flex-start;
      }

      h1 {
        max-width: 12ch;
      }

      .hero-stats,
      .product-grid {
        grid-template-columns: 1fr;
      }

      .promo-visual {
        grid-template-columns: 1fr;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --surface: Canvas;
        --surface-strong: Canvas;
        --text: CanvasText;
        --muted: CanvasText;
        --line: ButtonBorder;
        --accent: LinkText;
        --accent-strong: LinkText;
        --accent-soft: Canvas;
        --success: CanvasText;
        --shadow: none;
        --focus: Highlight;
      }

      .site-header,
      .hero-copy,
      .hero-aside,
      .section-card,
      .product-card,
      .deal-highlight,
      .story-card,
      .story-mini,
      .stat,
      .promo-card {
        border-color: ButtonBorder;
        box-shadow: none;
      }

      .brand-mark,
      .promo-bag {
        background: ButtonFace;
        color: ButtonText;
        border: 1px solid ButtonBorder;
      }

      .btn-primary,
      .filter-btn[aria-pressed="true"],
      .mini-btn.primary {
        background: ButtonFace;
        color: ButtonText;
        border-color: ButtonText;
      }
    }
  </style>
</head>
