      min-width: 0;
    }

    .stat strong {
      display: block;
      font-size: 1.2rem;
      margin-bottom: 0.15rem;
    }

    .stat span {
      color: var(--muted);
      font-size: 0.95rem;
    }

    .hero-aside {
      padding: 1rem;
      display: grid;
      gap: 1rem;
      overflow: hidden;
    }

    .promo-panel {
      position: relative;
      min-height: 100%;
      border-radius: 24px;
      overflow: hidden;
      background:
        linear-gradient(150deg, #f3dcc6 0%, #f7ece2 35%, #dbc0a5 100%);
      padding: 1.35rem;
      min-width: 0;
    }

    .promo-panel h2 {
      font-size: 1.25rem;
      margin-bottom: 0.75rem;
    }

    .promo-panel > .label {
      display: inline-flex;
      width: fit-content;
      margin-bottom: 0.75rem;
      padding: 0.35rem 0.65rem;
      border-radius: 999px;
      background: #ffffffb3;
      color: #3f2c1f;
      font-size: 0.85rem;
      font-weight: 700;
    }

    .promo-panel p {
      max-width: 24ch;
      color: #3f2c1f;
      margin-bottom: 1rem;
    }

    .promo-visual {
      margin-top: 1rem;
      display: grid;
      grid-template-columns: 1.2fr 0.8fr;
      gap: 0.75rem;
      align-items: stretch;
    }

    .promo-bag,
    .promo-card {
      border-radius: 20px;
      background: color-mix(in srgb, #ffffff 68%, transparent);
      border: 1px solid color-mix(in srgb, #ffffff 60%, transparent);
      min-width: 0;
    }

    .promo-bag {
      padding: 1rem;
      display: grid;
      align-content: end;
      min-height: 250px;
      background-image:
        radial-gradient(circle at 30% 25%, #ffffff 0 3%, transparent 3.2%),
        linear-gradient(180deg, #7b4a22 0%, #965e2f 100%);
      color: var(--surface-strong);
    }

    .promo-bag .label {
      display: inline-flex;
      width: fit-content;
      margin-bottom: auto;
      padding: 0.35rem 0.65rem;
      border-radius: 999px;
      background: #ffffff1a;
      font-size: 0.85rem;
    }

    .promo-bag .bag-price {
      font-size: 1.35rem;
      font-weight: 800;
      margin-bottom: 0.1rem;
    }

    .promo-card {
      padding: 1rem;
      display: grid;
      gap: 0.75rem;
    }

    .deal-timer {
      display: flex;
      flex-wrap: wrap;
      gap: 0.55rem;
    }

    .time-chip {
      flex: 1 1 5rem;
      text-align: center;
      padding: 0.7rem 0.45rem;
      border-radius: 16px;
      background: var(--surface-strong);
      border: 1px solid var(--line);
    }

    .time-chip strong {
      display: block;
      font-size: 1.2rem;
    }

    .time-chip span {
      color: var(--muted);
      font-size: 0.84rem;
    }

    .grid {
      display: grid;
      gap: 1.25rem;
    }

    .section-card {
      padding: clamp(1.25rem, 2vw, 1.8rem);
      margin-top: 1.5rem;
    }

    .section-head {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      align-items: end;
      gap: 1rem;
      margin-bottom: 1rem;
    }

    .section-head h2 {
      font-size: clamp(1.5rem, 2vw, 2rem);
      letter-spacing: -0.03em;
      margin-bottom: 0.25rem;
    }

    .section-head p {
      color: var(--muted);
      margin-bottom: 0;
      max-width: 48ch;
    }

    .filter-bar {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
    }

    .filter-btn {
      min-height: 2.6rem;
      padding: 0.55rem 1rem;
      border-radius: 999px;
      border: 1px solid var(--line);
      background: var(--surface-strong);
      color: var(--text);
      cursor: pointer;
    }

    .filter-btn[aria-pressed="true"] {
      background: var(--text);
      border-color: var(--text);
      color: var(--surface-strong);
    }

    .product-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1rem;
    }

    .product-card {
      display: grid;
      background: var(--surface-strong);
      border: 1px solid var(--line);
      border-radius: 24px;
      overflow: hidden;
      min-width: 0;
    }

    .product-media {
      aspect-ratio: 4 / 3;
      background: #f1e6db;
      position: relative;
      overflow: hidden;
    }

    .product-media img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .badge {
      position: absolute;
      left: 1rem;
      top: 1rem;
      display: inline-flex;
      align-items: center;
      padding: 0.35rem 0.65rem;
      border-radius: 999px;
      background: var(--surface-strong);
      font-size: 0.82rem;
      font-weight: 700;
      box-shadow: 0 8px 20px #00000014;
    }

    .product-body {
      display: grid;
      gap: 0.7rem;
      padding: 1rem;
    }

    .product-title {
      font-size: 1.02rem;
      font-weight: 750;
      margin-bottom: 0.15rem;
    }

    .product-meta {
      display: flex;
      justify-content: space-between;
      gap: 0.75rem;
      color: var(--muted);
      font-size: 0.94rem;
    }

    .price {
      font-weight: 800;
      color: var(--text);
      white-space: nowrap;
    }

    .product-actions {
      display: flex;
      gap: 0.5rem;
      flex-wrap: wrap;
      margin-top: 0.15rem;
    }

    .mini-btn {
      min-height: 2.6rem;
      padding: 0.5rem 0.9rem;
      border-radius: 999px;
      border: 1px solid var(--line);
      background: var(--surface);
      color: var(--text);
      cursor: pointer;
    }

    .mini-btn.primary {
      background: var(--text);
      border-color: var(--text);
      color: var(--surface-strong);
    }

    .mini-btn:hover,
    .mini-btn:focus-visible {
      border-color: var(--accent);
      color: var(--accent-strong);
    }

    .mini-btn.primary:hover,
    .mini-btn.primary:focus-visible {
      background: var(--accent-strong);
      border-color: var(--accent-strong);
      color: var(--surface-strong);
    }

    .deal-layout {
      display: grid;
      grid-template-columns: 1fr 1.15fr;
      gap: 1rem;
      align-items: stretch;
    }

    .deal-highlight {
      padding: 1.25rem;
      border-radius: 24px;
      background: linear-gradient(160deg, #fff3e6 0%, #f4deca 100%);
      border: 1px solid color-mix(in srgb, var(--line) 75%, transparent);
      min-width: 0;
    }

    .deal-highlight h3 {
      font-size: 1.45rem;
      margin-bottom: 0.6rem;
    }

    .deal-highlight p {
      color: var(--muted);
      margin-bottom: 1rem;
    }

    .deal-bundle {
      display: grid;
      gap: 0.85rem;
    }

    .deal-row {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      padding: 0.85rem 0;
      border-top: 1px solid color-mix(in srgb, var(--line) 88%, transparent);
      min-width: 0;
    }

    .deal-row:first-of-type {
      border-top: 0;
      padding-top: 0;
    }

    .deal-row strong {
      display: block;
      margin-bottom: 0.2rem;
    }

    .deal-row span {
      color: var(--muted);
      font-size: 0.94rem;
    }

    .deal-row .price {
      font-size: 1.05rem;
      align-self: center;
    }

    .editorial-grid {
      display: grid;
      grid-template-columns: 1.25fr 0.75fr;
      gap: 1rem;
      align-items: stretch;
    }

    .story-card {
      display: grid;
      grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
      gap: 0;
      background: var(--surface-strong);
      border: 1px solid var(--line);
      border-radius: 24px;
      overflow: hidden;
      min-width: 0;
    }

    .story-card figure {
      margin: 0;
      min-width: 0;
      min-height: 100%;
    }

    .story-card img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .story-body {
      padding: 1.2rem;
      display: grid;
      align-content: center;
      gap: 0.75rem;
      min-width: 0;
    }

    .story-body h3 {
      font-size: 1.35rem;
      margin-bottom: 0.15rem;
    }

    .story-body p {
      color: var(--muted);
      margin-bottom: 0;
    }

    .story-list {
      display: grid;
      gap: 0.85rem;
    }

    .story-mini {
      padding: 1rem;
      border-radius: 22px;
      background: var(--surface-strong);
      border: 1px solid var(--line);
      min-width: 0;
    }

    .story-mini p {
      color: var(--muted);
      margin-bottom: 0.85rem;
    }

    .story-mini a {
      font-weight: 700;
    }

    .status {
      margin-top: 0.9rem;
      min-height: 1.5rem;
      color: var(--success);
      font-weight: 650;
    }

    .footer {
      padding: 1.5rem 0 2.5rem;
      color: var(--muted);
    }

    .footer-inner {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: 1rem;
      padding-top: 1rem;
      border-top: 1px solid var(--line);
    }

    .footer-links {
      display: flex;
      flex-wrap: wrap;
      gap: 1rem;
    }

    :focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    @media (max-width: 1024px) {
      .hero,
      .deal-layout,
      .editorial-grid {
        grid-template-columns: 1fr;
      }

      .product-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .story-card {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width: 720px) {
      .header-inner {
        flex-direction: column;
        align-items: flex-start;
      }

      .main-nav {
        margin-left: 0;
        width: 100%;
      }

      .main-nav ul {
        justify-content: flex-start;
      }

      h1 {
        max-width: 12ch;
      }

      .hero-stats,
      .product-grid {
        grid-template-columns: 1fr;
      }

      .promo-visual {
        grid-template-columns: 1fr;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --surface: Canvas;
        --surface-strong: Canvas;
        --text: CanvasText;
        --muted: CanvasText;
        --line: ButtonBorder;
        --accent: LinkText;
        --accent-strong: LinkText;
        --accent-soft: Canvas;
        --success: CanvasText;
        --shadow: none;
        --focus: Highlight;
      }

      .site-header,
      .hero-copy,
      .hero-aside,
      .section-card,
      .product-card,
      .deal-highlight,
      .story-card,
      .story-mini,
      .stat,
      .promo-card {
        border-color: ButtonBorder;
        box-shadow: none;
      }

      .brand-mark,
      .promo-bag {
        background: ButtonFace;
        color: ButtonText;
        border: 1px solid ButtonBorder;
      }

      .btn-primary,
      .filter-btn[aria-pressed="true"],
      .mini-btn.primary {
        background: ButtonFace;
        color: ButtonText;
        border-color: ButtonText;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <header class="site-header">
    <div class="shell header-inner">
      <a class="brand" href="#top" aria-label="Northstar Retail home">
        <span class="brand-mark" aria-hidden="true">N</span>
        <span>Northstar Retail</span>
      </a>

      <nav class="main-nav" aria-label="Primary">
        <ul>
          <li><a href="#featured">Featured</a></li>
          <li><a href="#deals">Deals</a></li>
          <li><a href="#stories">Stories</a></li>
          <li><a href="#newsletter">Journal</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main id="main">
    <div class="shell" id="top">
      <section class="hero" aria-labelledby="hero-heading">
        <div class="hero-copy">
          <p class="eyebrow">New season, refined essentials</p>
          <h1 id="hero-heading">Modern pieces for every part of the week.</h1>
          <p class="lede">Discover elevated basics, special buys, and curated editorial picks designed to make a retail home page feel effortless, premium, and easy to shop.</p>
          <div class="hero-actions">
            <a class="btn btn-primary" href="#featured">Shop featured</a>
            <a class="btn btn-secondary" href="#deals">See today's deals</a>
          </div>
          <div class="hero-stats" aria-label="Store highlights">
            <div class="stat">
              <strong>120+</strong>
              <span>new arrivals this month</span>
            </div>
            <div class="stat">
              <strong>2-day</strong>
              <span>free shipping over $75</span>
            </div>
            <div class="stat">
              <strong>4.8/5</strong>
              <span>customer rating average</span>
            </div>
          </div>
        </div>

        <aside class="hero-aside" aria-label="Featured promotion">
          <div class="promo-panel">
            <p class="label">Limited time</p>
            <h2>Spring carryall bundle</h2>
            <p>Build a polished everyday rotation with a bag, knit, and shoe edit priced for the weekend.</p>
            <div class="promo-visual">
              <div class="promo-bag" aria-hidden="true">
                <span class="label">Best seller</span>
                <div class="bag-price">$118</div>
                <div>Canvas Carryall</div>
              </div>
              <div class="promo-card">
                <strong>Bundle savings</strong>
                <p style="margin:0;color:var(--muted);">Save 20% when you buy any three accessories.</p>
                <a class="btn btn-secondary" href="#deals" style="width:100%;">Shop the bundle</a>
              </div>
            </div>
          </div>
        </aside>
      </section>

      <section class="section-card" id="featured" aria-labelledby="featured-heading">
        <div class="section-head">
          <div>
            <h2 id="featured-heading">Featured products</h2>
            <p>Top picks across apparel, accessories, and home goods, with category filters for quick browsing.</p>
          </div>
          <div class="filter-bar" role="toolbar" aria-label="Product filters">
            <button class="filter-btn" type="button" data-filter="all" aria-pressed="true">All</button>
            <button class="filter-btn" type="button" data-filter="apparel" aria-pressed="false">Apparel</button>
            <button class="filter-btn" type="button" data-filter="accessories" aria-pressed="false">Accessories</button>
            <button class="filter-btn" type="button" data-filter="home" aria-pressed="false">Home</button>
          </div>
        </div>

        <div class="product-grid" id="product-grid">
          <article class="product-card" data-category="apparel">
            <div class="product-media">
              <span class="badge">New</span>
              <img src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 900 675'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop stop-color='%23f7e8dc'/%3E%3Cstop offset='1' stop-color='%23c98a55'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='900' height='675' fill='url(%23g)'/%3E%3Crect x='120' y='120' width='660' height='440' rx='36' fill='%23ffffff' fill-opacity='.16'/%3E%3Cpath d='M220 424c84-86 176-129 288-129 82 0 149 19 195 53' fill='none' stroke='%23fff' stroke-width='38' stroke-linecap='round' stroke-opacity='.36'/%3E%3Ccircle cx='658' cy='206' r='82' fill='%23fff' fill-opacity='.24'/%3E%3C/svg%3E" alt="Model wearing a cream tailored jacket and relaxed trousers">
            </div>
            <div class="product-body">
              <div>
                <div class="product-title">Relaxed Tailored Set</div>
                <div class="product-meta"><span>Apparel</span><span class="price">$148</span></div>
              </div>
              <div class="product-actions">
                <button class="mini-btn primary" type="button" data-add-to-bag="Relaxed Tailored Set">Add to bag</button>
                <button class="mini-btn" type="button" data-save="Relaxed Tailored Set">Save</button>
              </div>
            </div>
