            </div>
            <div class="product-body">
              <div>
                <div class="product-title">Leather Crossbody</div>
                <div class="product-meta"><span>Accessories</span><span class="price">$92</span></div>
              </div>
              <div class="product-actions">
                <button class="mini-btn primary" type="button" data-add-to-bag="Leather Crossbody">Add to bag</button>
                <button class="mini-btn" type="button" data-save="Leather Crossbody">Save</button>
              </div>
            </div>
          </article>

          <article class="product-card" data-category="home">
            <div class="product-media">
              <span class="badge">Editor pick</span>
              <img src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 900 675'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop stop-color='%23efe7dc'/%3E%3Cstop offset='1' stop-color='%23c6b39b'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='900' height='675' fill='url(%23g)'/%3E%3Crect x='95' y='380' width='710' height='34' rx='17' fill='%23625348' fill-opacity='.38'/%3E%3Crect x='160' y='220' width='96' height='180' rx='16' fill='%23fff' fill-opacity='.42'/%3E%3Ccircle cx='602' cy='254' r='86' fill='%23fff' fill-opacity='.24'/%3E%3Cpath d='M470 190c34 22 50 57 50 100 0 47-17 86-55 118' fill='none' stroke='%23fff' stroke-width='28' stroke-linecap='round' stroke-opacity='.3'/%3E%3C/svg%3E" alt="Minimal dining table with ceramic decor and soft daylight">
            </div>
            <div class="product-body">
              <div>
                <div class="product-title">Ceramic Table Edit</div>
                <div class="product-meta"><span>Home</span><span class="price">$64</span></div>
              </div>
              <div class="product-actions">
                <button class="mini-btn primary" type="button" data-add-to-bag="Ceramic Table Edit">Add to bag</button>
                <button class="mini-btn" type="button" data-save="Ceramic Table Edit">Save</button>
              </div>
            </div>
          </article>

          <article class="product-card" data-category="apparel">
            <div class="product-media">
              <span class="badge">Trending</span>
              <img src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 900 675'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop stop-color='%23efe6d8'/%3E%3Cstop offset='1' stop-color='%23ae7b54'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='900' height='675' fill='url(%23g)'/%3E%3Cpath d='M284 170c32 34 67 50 116 50s84-16 116-50l96 84-72 322H260l-72-322z' fill='%23fff' fill-opacity='.17'/%3E%3Cpath d='M318 244c28 26 56 39 82 39 29 0 57-13 84-39' fill='none' stroke='%23fff' stroke-width='24' stroke-linecap='round' stroke-opacity='.38'/%3E%3Cpath d='M360 304c30 17 60 26 90 26s60-9 90-26' fill='none' stroke='%23fff' stroke-width='20' stroke-linecap='round' stroke-opacity='.24'/%3E%3C/svg%3E" alt="Neutral knit sweater folded neatly with soft texture visible">
            </div>
            <div class="product-body">
              <div>
                <div class="product-title">Everyday Knit Crew</div>
