  <script>
    const statusEl = document.getElementById("feature-status");
    const productCards = Array.from(document.querySelectorAll(".product-card"));
    const filterButtons = Array.from(document.querySelectorAll(".filter-btn"));

    function setStatus(message) {
      statusEl.textContent = message;
    }

    function applyFilter(filter) {
      productCards.forEach((card) => {
        const match = filter === "all" || card.dataset.category === filter;
        card.hidden = !match;
      });

      filterButtons.forEach((button) => {
        const active = button.dataset.filter === filter;
        button.setAttribute("aria-pressed", String(active));
      });

      const visibleCount = productCards.filter((card) => !card.hidden).length;
      setStatus(`${visibleCount} product${visibleCount === 1 ? "" : "s"} shown for ${filter === "all" ? "all categories" : filter}.`);
    }

    filterButtons.forEach((button) => {
      button.addEventListener("click", () => applyFilter(button.dataset.filter));
    });

    document.querySelectorAll("[data-add-to-bag]").forEach((button) => {
      button.addEventListener("click", () => {
        setStatus(`${button.dataset.addToBag} added to your bag.`);
      });
    });

    document.querySelectorAll("[data-save]").forEach((button) => {
      button.addEventListener("click", () => {
        setStatus(`${button.dataset.save} saved for later.`);
      });
    });

    const endTime = Date.now() + (48 * 60 * 60 * 1000) + (24 * 60 * 1000);
    const timerEls = {
      days: document.getElementById("days"),
      hours: document.getElementById("hours"),
      minutes: document.getElementById("minutes"),
      seconds: document.getElementById("seconds")
    };

    function tick() {
      const remaining = Math.max(0, endTime - Date.now());
      const totalSeconds = Math.floor(remaining / 1000);
      const days = Math.floor(totalSeconds / 86400);
      const hours = Math.floor((totalSeconds % 86400) / 3600);
      const minutes = Math.floor((totalSeconds % 3600) / 60);
      const seconds = totalSeconds % 60;

      timerEls.days.textContent = String(days).padStart(2, "0");
      timerEls.hours.textContent = String(hours).padStart(2, "0");
      timerEls.minutes.textContent = String(minutes).padStart(2, "0");
      timerEls.seconds.textContent = String(seconds).padStart(2, "0");
    }

    applyFilter("all");
    tick();
    setInterval(tick, 1000);
  </script>
